import { Injectable } from '@angular/core';
import { Router } from '@angular/router';
import { ProductsService, Product } from './products.service';
import { CartService } from './cart.service';
import { OrdersService, OrderOut, OrderCreate, OrderItemIn } from './orders.service';
import { AuthService } from './auth.service';
import { Observable, throwError } from 'rxjs';
import { switchMap, map } from 'rxjs/operators';

@Injectable({ providedIn: 'root' })
export class AiAgentService {
  constructor(
    private products: ProductsService,
    private cart: CartService,
    private orders: OrdersService,
    private auth: AuthService,
    private router: Router
  ) {}

  buyProductByName(name: string): Observable<OrderOut> {
    const q = name?.trim();
    if (!q) return throwError(() => new Error('product name required'));
    return this.products.list({ q, in_stock: true }).pipe(
      switchMap((list: Product[]) => {
        if (!list || list.length === 0) return throwError(() => new Error('no product found'));
        const p = list[0];
        this.cart.add(p);
        const items: OrderItemIn[] = this.cart.items().map(i => ({ product_id: i.product.id, quantity: i.quantity }));
        const payload: OrderCreate = {
          items,
          payment_method: 'CARD',
          shipping_address: this.auth.savedAddress() || 'N/A',
          contact_name: this.auth.user()?.name || 'Guest User',
          contact_email: this.auth.user()?.email || 'guest@example.com',
          contact_phone: this.auth.savedPhone() || ''
        };
        return this.orders.create(payload);
      }),
      map((order: OrderOut) => {
        if (this.auth.isLoggedIn()) this.router.navigateByUrl(`/payment/${order.id}`);
        else this.router.navigateByUrl('/login');
        return order;
      })
    );
  }
}
